use graham_ledger::{Ledger,OpeningInput,OpeningPosition,TradeInput,DividendInput,ValuationQuery,ValuationResponse,ValuationPoint,ValuationError,QuoteKey};
fn now()->i64{chrono::DateTime::parse_from_rfc3339("2026-10-27T01:00:00Z").unwrap().timestamp()}
fn key(code:&str)->QuoteKey{QuoteKey{market:"CN".into(),code:code.into(),kind:"stock".into()}}
fn opening(l:&mut Ledger,name:&str,currency:&str,key:QuoteKey,cost:&str)->String{let a=l.create_account(name,currency).unwrap();l.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-22".into(),cash:"0".into(),positions:vec![OpeningPosition{market:key.market,code:key.code,kind:key.kind,name:name.into(),currency:currency.into(),quantity:"10".into(),cost:cost.into(),reference_price:None}],note:"".into()},None).unwrap();a}
fn price(l:&mut Ledger,q:&ValuationQuery,key:QuoteKey,value:&str,currency:&str){let job=l.begin_analysis_refresh(q,now()).unwrap().unwrap();let fx=key.kind=="fx";l.finish_valuation_refresh(&job,&ValuationResponse{feed:"valuation".into(),points:vec![ValuationPoint{key,date:q.date.clone(),value:value.into(),currency:currency.into(),source:if fx{"yfinance / Yahoo Finance"}else{"AKShare / 新浪"}.into(),basis:if fx{"daily_close"}else{"unadjusted"}.into(),source_time:Some(if fx{"2026-10-23 [Europe/London]"}else{"2026-10-23 [Asia/Shanghai]"}.into()),quoted_at:None}],errors:vec![],error:None},now()+1).unwrap();}
fn query(ids:Vec<String>)->ValuationQuery{ValuationQuery{account_ids:ids,currency:"CNY".into(),date:Some("2026-10-23".into())}}
fn net(state:&graham_ledger::AnalysisState)->&graham_ledger::AnalysisContribution{state.contributions.iter().find(|c|c.metric=="net").unwrap()}
#[test]
fn an_account_before_its_verified_opening_keeps_the_merged_contribution_incomplete(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();opening(&mut l,"已知账户","CNY",key("600036"),"100");let b=l.create_account("起点未知账户","CNY").unwrap();l.save_opening(&OpeningInput{account_id:b,occurred_on:"2026-10-26".into(),cash:"100".into(),positions:vec![],note:"".into()},None).unwrap();let q=query(vec![]);price(&mut l,&q,key("600036"),"13","CNY");let state=l.analysis(&q,now()+2).unwrap();assert!(!state.asset_complete);assert!(!state.missing.is_empty());assert_eq!(net(&state).known_total.as_deref(),Some("30.00"));assert!(!net(&state).complete,"Unknown account holdings are not zero contribution");
}

#[test]
fn same_security_merges_across_accounts_without_losing_negative_contributions_or_archived_accounts(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=opening(&mut l,"甲","CNY",key("600036"),"100");let b=opening(&mut l,"乙","CNY",key("600036"),"200");let mut q=query(vec![]);price(&mut l,&q,key("600036"),"13","CNY");l.set_account_archived(&b,true).unwrap();let all=l.analysis(&q,now()+2).unwrap();assert_eq!(all.total_assets.as_deref(),Some("260.00"));assert_eq!(all.rows.len(),2);assert_eq!(net(&all).known_total.as_deref(),Some("-40.00"));assert_eq!(net(&all).bars.len(),1);assert_eq!(net(&all).bars[0].share.as_deref(),Some("100.00"));
 q.account_ids=vec![a.clone()];assert_eq!(net(&l.analysis(&q,now()+2).unwrap()).known_total.as_deref(),Some("30.00"));q.account_ids=vec![b];assert_eq!(net(&l.analysis(&q,now()+2).unwrap()).known_total.as_deref(),Some("-70.00"));let snapshot=l.snapshot().unwrap();let o=snapshot.openings.iter().find(|o|o.input.account_id==a).unwrap();let mut corrected=o.input.clone();corrected.positions[0].cost="120".into();l.save_opening(&corrected,Some(o.revision_id)).unwrap();q.account_ids=vec![];assert_eq!(net(&l.analysis(&q,now()+2).unwrap()).known_total.as_deref(),Some("-60.00"));
}
#[test]
fn closed_foreign_security_fetches_fx_without_price_and_rounds_negative_profit_symmetrically(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let us=QuoteKey{market:"US".into(),code:"AAPL".into(),kind:"stock".into()};let a=opening(&mut l,"美元已清仓","USD",us,"100");let b=l.create_account("范围外美元","USD").unwrap();l.record_trade(&TradeInput{account_id:a.clone(),occurred_on:"2026-10-23".into(),market:"US".into(),code:"AAPL".into(),kind:"stock".into(),name:"苹果".into(),currency:"USD".into(),side:"sell".into(),quantity:"10".into(),price:"9.99".into(),fee:"0.01".into(),tax:"0".into(),note:"".into()}).unwrap();l.record_movement(&graham_ledger::MovementInput{from_account_id:a.clone(),to_account_id:b,occurred_on:"2026-10-23".into(),kind:"transfer".into(),from_currency:"USD".into(),to_currency:"USD".into(),from_amount:"99.89".into(),to_amount:"99.89".into(),actual_rate:"1".into(),fee:"0".into(),fee_side:"from".into(),note:"".into()}).unwrap();let q=query(vec![a]);assert!(net(&l.analysis(&q,now()).unwrap()).known_total.is_none());let fx=QuoteKey{market:"USD".into(),code:"CNY".into(),kind:"fx".into()};price(&mut l,&q,fx,"7.5","CNY");let s=l.analysis(&q,now()+2).unwrap();assert_eq!(s.total_assets.as_deref(),Some("0.00"));assert_eq!(s.rows[0].quantity,"0");assert_eq!(s.rows[0].realized,"-0.11");assert_eq!(net(&s).known_total.as_deref(),Some("-0.83"));let rate=s.sources.iter().find(|s|s.key.kind=="fx").expect("Analysis must expose the FX used for the contribution");assert_eq!(rate.value.as_deref(),Some("7.5"));assert_eq!(rate.source_time.as_deref(),Some("2026-10-23 [Europe/London]"));assert_eq!(net(&s).bars[0].share.as_deref(),Some("100.00"));
}
#[test]
fn dividend_receivable_payment_does_not_duplicate_income_and_opening_covered_income_is_excluded(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=l.create_account("分红核对","CNY").unwrap();let mut input=DividendInput{account_id:a.clone(),occurred_on:"2026-10-21".into(),paid_on:Some("2026-10-26".into()),status:"paid".into(),market:"CN".into(),code:"600036".into(),kind:"stock".into(),name:"招商银行".into(),currency:"CNY".into(),gross:"7".into(),tax:"0".into(),net:"7".into(),note:"".into()};l.record_dividend(&input).unwrap();l.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-22".into(),cash:"100".into(),positions:vec![],note:"".into()},None).unwrap();input.occurred_on="2026-10-23".into();input.gross="10".into();input.tax="2".into();input.net="8".into();l.record_dividend(&input).unwrap();let mut q=query(vec![a]);let pending=l.analysis(&q,now()).unwrap();assert_eq!(pending.total_assets.as_deref(),Some("115.00"));assert_eq!(pending.rows[0].net_dividend,"8.00");assert_eq!(net(&pending).known_total.as_deref(),Some("8.00"));q.date=Some("2026-10-26".into());let paid=l.analysis(&q,now()).unwrap();assert_eq!(paid.total_assets,pending.total_assets);assert_eq!(net(&paid).known_total,net(&pending).known_total);
}
#[test]
fn fund_classification_is_explicitly_not_looked_through_and_empty_accounts_have_no_fake_contribution(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let fund=QuoteKey{market:"CN".into(),code:"510300".into(),kind:"etf".into()};let a=opening(&mut l,"基金","CNY",fund.clone(),"40");let q=query(vec![a]);price(&mut l,&q,fund,"4","CNY");let s=l.analysis(&q,now()+2).unwrap();assert_eq!(s.rows[0].industry,"基金（未穿透）");assert_eq!(net(&s).known_total.as_deref(),Some("0.00"));let empty=l.create_account("空账户","CNY").unwrap();let s=l.analysis(&ValuationQuery{account_ids:vec![empty],currency:"CNY".into(),date:None},now()).unwrap();assert!(s.rows.is_empty());assert!(net(&s).known_total.is_none());
}
#[test]
fn scoped_allocation_and_net_contribution_reconcile_without_pricing_unknown_holdings_at_cost(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=l.create_account("组合样例","CNY").unwrap();let positions=[("600036","招商银行","100"),("000001","未知行业样例","200")].into_iter().map(|(code,name,cost)|OpeningPosition{market:"CN".into(),code:code.into(),kind:"stock".into(),name:name.into(),currency:"CNY".into(),quantity:"10".into(),cost:cost.into(),reference_price:None}).collect();
 l.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-22".into(),cash:"100".into(),positions,note:"".into()},None).unwrap();l.record_trade(&TradeInput{account_id:a.clone(),occurred_on:"2026-10-23".into(),market:"CN".into(),code:"600036".into(),kind:"stock".into(),name:"招商银行".into(),currency:"CNY".into(),side:"sell".into(),quantity:"2".into(),price:"12".into(),fee:"1".into(),tax:"0".into(),note:"".into()}).unwrap();l.record_dividend(&DividendInput{account_id:a.clone(),occurred_on:"2026-10-23".into(),paid_on:Some("2026-10-26".into()),status:"paid".into(),market:"CN".into(),code:"600036".into(),kind:"stock".into(),name:"招商银行".into(),currency:"CNY".into(),gross:"10".into(),tax:"2".into(),net:"8".into(),note:"".into()}).unwrap();
 let before=l.snapshot().unwrap();let q=ValuationQuery{account_ids:vec![a],currency:"CNY".into(),date:Some("2026-10-23".into())};let job=l.begin_valuation_refresh(&q,now(),false).unwrap().unwrap();l.finish_valuation_refresh(&job,&ValuationResponse{feed:"valuation".into(),points:vec![ValuationPoint{key:key("600036"),date:q.date.clone(),value:"13".into(),currency:"CNY".into(),source:"AKShare / 新浪".into(),basis:"unadjusted".into(),source_time:Some("2026-10-23 [Asia/Shanghai]".into()),quoted_at:None}],errors:vec![ValuationError{key:key("000001"),error:"样例缺少收盘价".into(),invalidates:false}],error:None},now()+1).unwrap();let state=l.analysis(&q,now()+2).unwrap();
 assert_eq!(state.known_assets.as_deref(),Some("235.00"));assert!(state.total_assets.is_none());let row=state.rows.iter().find(|r|r.key.code=="600036").unwrap();assert_eq!(row.realized,"3.00");assert_eq!(row.unrealized.as_deref(),Some("24.00"));assert_eq!(row.net_dividend,"8.00");assert_eq!(row.net_contribution.as_deref(),Some("35.00"));let net=state.contributions.iter().find(|c|c.metric=="net").unwrap();assert_eq!(net.known_total.as_deref(),Some("35.00"));assert!(!net.complete);let unknown=net.bars.iter().find(|b|b.key.code=="000001").unwrap();assert!(unknown.amount.is_none()&&unknown.share.is_none());assert_eq!(net.bars.iter().find(|b|b.key.code=="600036").unwrap().share.as_deref(),Some("100.00"));assert!(state.allocations.iter().any(|g|g.dimension=="industry"&&g.label=="未分类"&&g.missing_count==1));assert_eq!(l.snapshot().unwrap().accounts,before.accounts);
}
